    add("    def _formatar_tempo(self, segundos):")
    add("        segundos = max(0.0, float(segundos))")
    add("        horas = int(segundos // 3600)")
    add("        minutos = int((segundos % 3600) // 60)")
    add("        resto = segundos % 60")
