    add("    def cronometro_iniciar(self, destino):")
    add("        if getattr(self, '_cronometro_rodando', False):")
    add("            return")
    add("        self._cronometro_rodando = True")
    add("        self._cronometro_acumulado = float(getattr(self, '_cronometro_acumulado', 0.0))")
    add("        self._cronometro_inicio = time.perf_counter()")
    add("        self._cronometro_tick(destino)")
    add("")
    add("    def _cronometro_tick(self, destino):")
    add("        if not getattr(self, '_cronometro_rodando', False):")
    add("            return")
    add("        atual = self._cronometro_acumulado + (time.perf_counter() - self._cronometro_inicio)")
    add("        self._definir_valor_componente(destino, self._formatar_tempo(atual))")
    add("        self.after(100, lambda: self._cronometro_tick(destino))")
    add("")
    add("    def cronometro_pausar(self, destino):")
    add("        if getattr(self, '_cronometro_rodando', False):")
    add("            self._cronometro_acumulado += time.perf_counter() - self._cronometro_inicio")
    add("        self._cronometro_rodando = False")
    add("        self._definir_valor_componente(destino, self._formatar_tempo(getattr(self, '_cronometro_acumulado', 0.0)))")
    add("")
    add("    def cronometro_zerar(self, destino):")
    add("        self._cronometro_rodando = False")
    add("        self._cronometro_acumulado = 0.0")
    add("        self._definir_valor_componente(destino, '00:00:00.0')")
