    add("    def temporizador_iniciar(self, origem, destino):")
    add("        if getattr(self, '_temporizador_rodando', False):")
    add("            return")
    add("        try:")
    add("            valor = int(float(str(self._valor_componente(origem)).replace(',', '.')))")
    add("        except (TypeError, ValueError):")
    add("            valor = 0")
    add("        if valor <= 0:")
    add("            messagebox.showwarning('Temporizador', 'Informe uma quantidade de segundos maior que zero.')")
    add("            return")
    add("        self._temporizador_restante = valor")
    add("        self._temporizador_rodando = True")
    add("        self._temporizador_tick(destino)")
    add("")
    add("    def _temporizador_tick(self, destino):")
    add("        if not getattr(self, '_temporizador_rodando', False):")
    add("            return")
    add("        restante = int(getattr(self, '_temporizador_restante', 0))")
    add("        self._definir_valor_componente(destino, self._formatar_tempo(restante))")
    add("        if restante <= 0:")
    add("            self._temporizador_rodando = False")
    add("            messagebox.showinfo('Temporizador', 'Tempo encerrado!')")
    add("            return")
    add("        self._temporizador_restante = restante - 1")
    add("        self.after(1000, lambda: self._temporizador_tick(destino))")
    add("")
    add("    def temporizador_pausar(self, destino):")
    add("        self._temporizador_rodando = False")
    add("        self._definir_valor_componente(destino, self._formatar_tempo(getattr(self, '_temporizador_restante', 0)))")
    add("")
    add("    def temporizador_zerar(self, destino):")
    add("        self._temporizador_rodando = False")
    add("        self._temporizador_restante = 0")
    add("        self._definir_valor_componente(destino, '00:00:00.0')")
