    add("    def gerar_senha_segura(self, campo_tamanho, campo_simbolos, destino):")
    add("        try:")
    add("            tamanho = int(float(str(self._valor_componente(campo_tamanho)).replace(',', '.')))")
    add("        except (TypeError, ValueError):")
    add("            tamanho = 12")
    add("        tamanho = min(max(tamanho, 8), 128)")
    add("        usar_simbolos = bool(self._valor_componente(campo_simbolos)) if campo_simbolos else True")
    add("        alfabeto = string.ascii_letters + string.digits")
    add("        if usar_simbolos:")
    add("            alfabeto += '!@#$%&*_-+=?'")
    add("        senha = ''.join(secrets.choice(alfabeto) for _ in range(tamanho))")
    add("        self._definir_valor_componente(destino, senha)")
